    "열 가지 항목: 상급 책임 소유자(프로그램 책임자가 대신함), 파트너, 단계, 일정 기준선, 목표일, 예산, 각 예산 항목의 자금 출처, 수행 신뢰도 평가, 위험, 종속 관계. 파트너는 수행 모델에 파트너가 있는 경우에만, 자금 출처는 예산 항목이 있는 경우에만 요구합니다. 프로그램과 그 하위 계획을 합쳐서 계산합니다.",
  "p.register_completeness.switch_on":
    "“등록부 없이는 자금 없음”이 켜져 있습니다. 불완전한 프로그램의 예산 항목 집행이나 확정 배정 예약은 거부되며 빠진 항목이 명시됩니다.",
  "p.register_completeness.switch_off":
    "“등록부 없이는 자금 없음”이 꺼져 있습니다. 불완전한 프로그램의 예산 항목 집행이나 확정 배정 예약은 진행되며 경고는 감사 추적에 남습니다.",
