    "팔로우하는 항목이 바뀌면 알림을 받습니다. 작업을 만들거나, 댓글을 달거나, 배정받으면 알림 설정에서 끄지 않은 한 그 작업을 팔로우하게 됩니다. 누가 팔로우하는지는 다른 사람에게 알려지지 않습니다. 계획은 이름으로 표시되고, 그 밖의 항목은 종류와 참조의 앞부분으로 표시됩니다.",
