  "p.hammock.heading": "해먹: 다른 작업을 아우르는 요약 작업",
  "p.hammock.says":
    "해먹은 이 계획에서 연결한 작업들의 가장 이른 시작일부터 가장 늦은 완료일까지로 날짜가 정해지는 요약 작업입니다. 종속 관계 네트워크에 속하지 않으므로 어떤 작업의 여유 시간이나 완료일도 바꾸지 않습니다. 작업은 기간, 업무량, 제약 조건, 종속 관계가 없고 계획된 시작일이 지워진 경우에만 해먹이 될 수 있으며, 다시 작업으로 되돌리면 모든 연결이 제거됩니다. 해먹은 이 계획의 작업이나 다른 해먹에 연결할 수 있으며, 자기 자신에게, 두 번, 순환하도록 연결할 수는 없습니다.",
