  "p.crossplan.task_says":
    "종속 관계는 이 작업을 읽을 수 있는 다른 계획의 작업과 연결합니다. 유형은 선택하지 않으면 완료-시작이며, 지연은 영업일 기준 -{max}에서 {max} 사이의 정수이고 음수 지연은 선행입니다. 같은 방식의 종속 관계를 두 번 만들 수 없고, 계획 간에 순환하도록 만들 수 없으며, 해먹과 연결할 수 없습니다. 반대쪽 끝을 읽을 수 없는 종속 관계는 개수만 세고 이름은 표시하지 않으며 일정에서 제외됩니다.",
