  "p.ccpm.says":
    "주사슬을 위해 각 작업에는 공격적 추정치(성공 확률이 약 반반)와 안전 추정치가 영업일 기준 1에서 {max} 사이의 정수로 필요하며, 공격적 추정치는 안전 추정치를 넘으면 안 됩니다. 표시되는 수치는 기록된 값이고, 없으면 위험 범위의 값, 그것도 없으면 배포 환경의 규칙이 도출한 값이며 각각 어느 것인지 밝힙니다. 마일스톤과 기간이 없는 작업은 추정하지 않습니다. 둘 다 비우면 기록된 값이 제거됩니다.",
